<?php
declare(strict_types=1);
$items = $cartItems;
$resolveCartImage = static function (array $item): ?string {
    $name = basename(trim((string) ($item['image_url'] ?? '')));
    $root = dirname(__DIR__, 3) . '/assets/products/';
    if ($name !== '' && is_file($root . $name)) return 'assets/products/' . $name;
    $jpg = pathinfo($name, PATHINFO_FILENAME) . '.jpg';
    return $name !== '' && is_file($root . $jpg) ? 'assets/products/' . $jpg : null;
};
?>
<link rel="stylesheet" href="resources/css/products.css"><link rel="stylesheet" href="resources/css/cart.css"><link rel="stylesheet" href="resources/css/cart-grid.css"><link rel="stylesheet" href="resources/css/cart-polish.css">
<section class="sol-container products-page cart-page">
    <header class="products-hero"><div><span class="sol-badge sol-badge--emerald">Solaris · Giỏ hàng</span><h1>Sản phẩm đã chọn</h1><p>Chọn thiết bị, điều chỉnh số lượng và chuyển cấu hình sang phần Đề mô của member3.</p></div><a class="sol-btn sol-btn--outline" href="index.php?page=products">← Tiếp tục mua sắm</a></header>
    <?php if (!$items): ?><div class="sol-glass-card products-empty"><div><strong>Giỏ hàng đang trống</strong><p>Hãy chọn thiết bị từ catalog để bắt đầu cấu hình.</p><a class="sol-btn sol-btn--solar" href="index.php?page=products">Xem sản phẩm</a></div></div><?php else: ?>
        <form method="post" class="sol-glass-card cart-table" id="cart-form"><input type="hidden" name="cart_action" value="demo_selected"><div class="cart-toolbar"><label class="cart-select-all"><input type="checkbox" id="select-all"> <span>Chọn tất cả</span></label><span id="selected-count">0 sản phẩm được chọn</span></div><div class="cart-items"><?php foreach ($items as $item): $image = $resolveCartImage($item); ?><article class="cart-item" data-price="<?= (float) $item['price'] ?>" data-id="<?= (int) $item['id'] ?>"><label class="cart-check-wrap"><input class="cart-check" type="checkbox" name="selected[]" value="<?= (int) $item['id'] ?>"><span></span></label><div class="cart-product-image"><?php if ($image): ?><img src="<?= htmlspecialchars($image, ENT_QUOTES, 'UTF-8') ?>" alt="<?= htmlspecialchars($item['name'], ENT_QUOTES, 'UTF-8') ?>"><?php else: ?><span>☀</span><?php endif; ?></div><div class="cart-product-info"><strong><?= htmlspecialchars($item['name']) ?></strong><small><?= htmlspecialchars($item['product_code']) ?></small><em><?= htmlspecialchars($item['category_name']) ?></em></div><div class="cart-unit-price"><?= number_format($item['price'], 0, ',', '.') ?> VNĐ</div><div class="quantity-control"><button type="button" class="quantity-button qty-minus" aria-label="Giảm số lượng">−</button><input class="cart-quantity" type="number" name="quantity[<?= (int) $item['id'] ?>]" value="<?= (int) $item['quantity'] ?>" min="1" max="99" aria-label="Số lượng"><button type="button" class="quantity-button qty-plus" aria-label="Tăng số lượng">+</button></div><strong class="item-total"><?= number_format($item['price'] * $item['quantity'], 0, ',', '.') ?> VNĐ</strong><button class="cart-remove" type="submit" name="cart_action" value="remove" formaction="index.php?page=cart" onclick="this.form.product_id.value='<?= (int) $item['id'] ?>'" aria-label="Xóa sản phẩm">×</button></article><?php endforeach; ?></div><input type="hidden" name="product_id"><footer class="cart-summary"><div><span>Tổng sản phẩm đã chọn</span><strong id="selected-total">0 VNĐ</strong></div><button class="sol-btn sol-btn--secondary" type="submit" formaction="index.php?page=cart" name="cart_action" value="update">Cập nhật giỏ</button><button class="sol-btn sol-btn--solar" type="submit">Đề mô sản phẩm đã chọn →</button></footer></form>
    <?php endif; ?>
</section>
<script>
(() => { const form=document.getElementById('cart-form'); if(!form)return; const all=document.getElementById('select-all'); const checks=[...form.querySelectorAll('.cart-check')]; const money=value=>new Intl.NumberFormat('vi-VN').format(value)+' VNĐ'; const refresh=()=>{let sum=0;let selected=0;checks.forEach(check=>{const row=check.closest('.cart-item');const input=row.querySelector('.cart-quantity');const qty=Math.max(1,Math.min(99,Number(input.value)||1));input.value=qty;row.querySelector('.item-total').textContent=money(Number(row.dataset.price)*qty);if(check.checked){sum+=Number(row.dataset.price)*qty;selected++;}});document.getElementById('selected-total').textContent=money(sum);document.getElementById('selected-count').textContent=selected+' sản phẩm được chọn';all.checked=checks.length>0&&selected===checks.length;}; all.addEventListener('change',()=>{checks.forEach(check=>check.checked=all.checked);refresh();});checks.forEach(check=>check.addEventListener('change',refresh));form.querySelectorAll('.cart-quantity').forEach(input=>input.addEventListener('input',refresh));form.querySelectorAll('.qty-minus').forEach(button=>button.addEventListener('click',()=>{const input=button.parentElement.querySelector('.cart-quantity');input.value=Math.max(1,(Number(input.value)||1)-1);refresh();}));form.querySelectorAll('.qty-plus').forEach(button=>button.addEventListener('click',()=>{const input=button.parentElement.querySelector('.cart-quantity');input.value=Math.min(99,(Number(input.value)||1)+1);refresh();}));refresh();})();
</script>
